import React, { useState, useEffect, useRef } from 'react';
import { Send, X, User, Clock, AlertCircle } from 'lucide-react';

const ChatWindow = ({ 
  conversation, 
  messages, 
  loading, 
  onSendMessage, 
  onClose,
  isAdmin,
  user 
}) => {
  const [inputMessage, setInputMessage] = useState('');
  const [sending, setSending] = useState(false);
  const messagesEndRef = useRef(null);

  const getOtherUserName = () => {
    if (isAdmin) {
      return `${conversation.user_first_name || ''} ${conversation.user_last_name || ''}`.trim() || 'Utilisateur';
    } else {
      return `${conversation.admin_first_name || ''} ${conversation.admin_last_name || ''}`.trim() || 'Conseiller';
    }
  };

  const getInitials = (name) => {
    if (!name) return '?';
    const names = name.split(' ');
    if (names.length >= 2) {
      return (names[0].charAt(0) + names[1].charAt(0)).toUpperCase();
    }
    return name.charAt(0).toUpperCase();
  };

  const handleSend = async () => {
    if (!inputMessage.trim() || sending) return;

    try {
      setSending(true);
      await onSendMessage(conversation.id, inputMessage.trim());
      setInputMessage('');
    } catch (error) {
      console.error('Erreur envoi message:', error);
    } finally {
      setSending(false);
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const formatTime = (dateString) => {
    try {
      const date = new Date(dateString);
      return date.toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' });
    } catch {
      return '--:--';
    }
  };

  return (
    <div className="bg-gradient-to-br from-white to-white/80 dark:from-neutral-900 dark:to-neutral-900/80 backdrop-blur-xl rounded-3xl shadow-2xl border border-white/40 dark:border-neutral-800/60 h-[600px] flex flex-col">
      {/* Header */}
      <div className="p-4 sm:p-6 border-b border-neutral-200/50 dark:border-neutral-800/50 flex-shrink-0">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="h-10 w-10 rounded-full bg-gradient-to-r from-primary-500 to-secondary-500 flex items-center justify-center text-white font-bold">
              {getInitials(getOtherUserName())}
            </div>
            <div>
              <h3 className="font-bold text-neutral-900 dark:text-white">
                {getOtherUserName()}
              </h3>
              <div className="flex items-center gap-2">
                <div className="h-2 w-2 bg-green-500 rounded-full"></div>
                <p className="text-xs text-neutral-500">En ligne</p>
              </div>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-lg md:hidden"
          >
            <X className="w-5 h-5" />
          </button>
        </div>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4">
        {loading ? (
          <div className="flex items-center justify-center h-full">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary-500"></div>
          </div>
        ) : messages.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full text-center">
            <User className="h-12 w-12 text-neutral-400 mb-3" />
            <p className="text-neutral-500">Aucun message. Commencez la conversation !</p>
          </div>
        ) : (
          <div className="space-y-4">
            {messages.map((message) => {
              const isCurrentUser = message.sender_id === user.id;

              return (
                <div
                  key={message.id}
                  className={`flex ${isCurrentUser ? 'justify-end' : 'justify-start'}`}
                >
                  <div className={`max-w-[80%] rounded-2xl p-3 ${
                    isCurrentUser
                      ? 'bg-gradient-to-r from-primary-500 to-secondary-500 text-white rounded-br-none'
                      : 'bg-neutral-100 dark:bg-neutral-800 text-neutral-900 dark:text-white rounded-bl-none'
                  }`}>
                    <p className="text-sm">{message.content}</p>
                    <div className={`flex items-center gap-1 mt-1 text-xs ${
                      isCurrentUser ? 'text-white/80' : 'text-neutral-500'
                    }`}>
                      <Clock className="w-3 h-3" />
                      <span>{formatTime(message.created_at)}</span>
                    </div>
                  </div>
                </div>
              );
            })}
            <div ref={messagesEndRef} />
          </div>
        )}
      </div>

      {/* Input */}
      <div className="p-4 border-t border-neutral-200/50 dark:border-neutral-800/50 flex-shrink-0">
        <div className="flex items-center gap-2">
          <div className="flex-1">
            <input
              type="text"
              value={inputMessage}
              onChange={(e) => setInputMessage(e.target.value)}
              onKeyPress={handleKeyPress}
              placeholder="Écrivez votre message..."
              className="w-full px-4 py-3 bg-neutral-100 dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-xl text-sm text-neutral-900 dark:text-white placeholder-neutral-500 focus:outline-none focus:ring-2 focus:ring-primary-500"
              disabled={sending}
            />
          </div>
          <button
            onClick={handleSend}
            disabled={!inputMessage.trim() || sending}
            className="p-3 rounded-xl bg-gradient-to-r from-primary-500 to-secondary-500 text-white hover:opacity-90 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {sending ? (
              <div className="animate-spin rounded-full h-5 w-5 border-2 border-white border-t-transparent"></div>
            ) : (
              <Send className="w-5 h-5" />
            )}
          </button>
        </div>
      </div>
    </div>
  );
};

export default ChatWindow;
